/// <mls fileReference="_102034_/l1/server/layer_1_external/connections/external/externalGeneratedSecret.test.ts" enhancement="_blank" />
// rt331 s1: a secret the declaration marks `generated` is made by the platform the first time it is needed, and kept.
import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { describe, it } from 'node:test';
import { exampleExternalSystem } from '/_102034_/testing/connections/externalFixtures.js';
import {
  createExternalSettingsStore,
  memorySettingsDb,
  type ExternalSettingsDb,
} from '/_102034_/l1/server/layer_1_external/connections/external/externalSettingsStore.js';
import { createExternalSender, type ExternalRef, type ExternalRecordEvent } from '/_102034_/l1/server/layer_1_external/connections/external/sendExternal.js';
import { validateExternalSystemDeclaration, type ExternalSystemDeclaration } from '/_102034_/l2/shared/contracts/connections/externalSystem.js';

const KEY = randomBytes(32);
/** The valid example system, with its signing key generated by the platform (the secret of the `notify` call and of the `receive` hook). */
const declaration: ExternalSystemDeclaration = {
  ...exampleExternalSystem,
  settings: [
    { id: 'account', secret: false },
    { id: 'signingKey', secret: true, generated: true },
    { id: 'manualKey', secret: true },
  ],
};
const ref: ExternalRef = { projectId: '102034', moduleId: 'exampleModule', systemId: declaration.systemId };
const GEN = 'signingKey';

function storeOf(key: Buffer | null = KEY, lines: string[] = []) {
  const db = memorySettingsDb();
  const writes: unknown[][] = [];
  const recording: ExternalSettingsDb = {
    async query(sql, params = []) {
      if (!sql.startsWith('SELECT')) writes.push([...params]);
      return db.query(sql, params);
    },
  };
  return { store: createExternalSettingsStore({ declarationOf: () => declaration, moduleOf: () => ref.moduleId, db: recording, key, log: (line) => { lines.push(line); } }), writes, lines };
}

describe('rt331 s1: the contract', () => {
  const base = (settings: unknown[]) => ({ ...exampleExternalSystem, settings });
  it('generated is valid only as `true` and only with secret: true', () => {
    assert.deepEqual(validateExternalSystemDeclaration(base([{ id: 'k', secret: true, generated: true }])).filter((item) => /generated/u.test(item.message)), []);
    assert.match(validateExternalSystemDeclaration(base([{ id: 'k', secret: false, generated: true }])).map((item) => item.message).join('\n'), /generated is only valid with secret: true/u);
    assert.match(validateExternalSystemDeclaration(base([{ id: 'k', secret: true, generated: false }])).map((item) => item.message).join('\n'), /generated is present but not true/u);
  });
});

describe('rt331 s1: ensureGeneratedSecret', () => {
  it('makes 32 random bytes in base64url the first time, and the same value after', async () => {
    const { store } = storeOf();
    const first = await store.ensureGeneratedSecret(ref, GEN);
    assert.equal(first.ok && first.value?.length, 43);
    assert.match(first.ok ? first.value ?? '' : '', /^[A-Za-z0-9_-]{43}$/u);
    const second = await store.ensureGeneratedSecret(ref, GEN);
    assert.deepEqual(second, first);
    const read = await store.secretOf(ref, GEN);
    assert.deepEqual(read, first, 'what the hook reads (secretOf) is what was made');
  });

  it('two at the same time get the same value and one row', async () => {
    const { store, writes } = storeOf();
    const [a, b] = await Promise.all([store.ensureGeneratedSecret(ref, GEN), store.ensureGeneratedSecret(ref, GEN)]);
    assert.deepEqual(a, b);
    assert.equal(a.ok && typeof a.value, 'string');
    assert.ok(writes.length >= 1);
    assert.deepEqual(await store.secretOf(ref, GEN), a);
  });

  it('a value typed by hand before stays as it is (the VM value keeps working)', async () => {
    // Written by the old path: the declaration of that time had no `generated`.
    const db = memorySettingsDb();
    const hand = createExternalSettingsStore({ declarationOf: () => ({ ...declaration, settings: [{ id: GEN, secret: true }] }), moduleOf: () => ref.moduleId, db, key: KEY });
    assert.deepEqual(await hand.set(ref, GEN, 'typed-by-hand-123', 'wagner'), { ok: true });
    const now = createExternalSettingsStore({ declarationOf: () => declaration, moduleOf: () => ref.moduleId, db, key: KEY });
    assert.deepEqual(await now.ensureGeneratedSecret(ref, GEN), { ok: true, value: 'typed-by-hand-123' });
    assert.deepEqual(await now.secretOf(ref, GEN), { ok: true, value: 'typed-by-hand-123' });
  });

  it('only a `generated` secret is made; anything else is left to the person; without the key of the VM nothing is made', async () => {
    const { store, writes } = storeOf();
    assert.deepEqual(await store.ensureGeneratedSecret(ref, 'manualKey'), { ok: true, value: undefined });
    assert.deepEqual(await store.ensureGeneratedSecret(ref, 'region'), { ok: true, value: undefined });
    assert.equal(writes.length, 0);
    const lines: string[] = [];
    const none = storeOf(null, lines);
    assert.deepEqual(await none.store.ensureGeneratedSecret(ref, GEN), { ok: false, code: 'disabled' });
    assert.equal(none.writes.length, 0, 'no plaintext, nothing stored');
  });

  it('the panel cannot write a generated setting (it can write the others)', async () => {
    const { store } = storeOf();
    assert.deepEqual(await store.set(ref, GEN, 'anything', 'admin'), { ok: false, code: 'generated' });
    assert.deepEqual(await store.set(ref, 'manualKey', 'sk-hand', 'admin'), { ok: true });
  });

  it('the value is stored sealed, never in the clear', async () => {
    const { store, writes } = storeOf();
    const made = await store.ensureGeneratedSecret(ref, GEN);
    const value = made.ok ? made.value ?? '' : '';
    assert.ok(value.length > 0);
    assert.equal(JSON.stringify(writes).includes(value), false);
  });
});

describe('rt331 s1: the outbound call makes the secret it cites', () => {
  function senderOf(store: ReturnType<typeof storeOf>['store'], seen: Array<Record<string, string>>, events: ExternalRecordEvent[], decl: ExternalSystemDeclaration = declaration) {
    return createExternalSender({
      declarationOf: () => decl,
      settingOf: async () => 'acme',
      secretOf: async (r, id) => { const read = await store.secretOf(r, id); return read.ok ? read.value ?? null : null; },
      ensureSecret: async (r, id) => { const read = await store.ensureGeneratedSecret(r, id); return read.ok ? read.value ?? null : null; },
      record: (event) => { events.push(event); },
      transport: async (call) => { seen.push(call.headers); return { status: 200, headers: { 'content-type': 'application/json' }, body: '{"sent":true}' }; },
      resolveHost: async () => ['8.8.8.8'],
    });
  }
  const notify = { method: 'POST' as const, path: '/notify', headers: { 'x-token': '{{secret:signingKey}}' }, body: '{}' };

  it('{{secret:<id>}} of a generated setting without value is made and sent; a second call sends the same; the record never carries it', async () => {
    const { store } = storeOf();
    const seen: Array<Record<string, string>> = [];
    const events: ExternalRecordEvent[] = [];
    const sender = senderOf(store, seen, events);
    const first = await sender.sendExternal(ref, 'notify', notify, { organizationId: 'org' });
    const second = await sender.sendExternal(ref, 'notify', notify, { organizationId: 'org' });
    assert.equal(first.ok, true, JSON.stringify(first));
    assert.equal(second.ok, true);
    const sentFirst = seen[0]?.['x-token'];
    assert.match(sentFirst ?? '', /^[A-Za-z0-9_-]{43}$/u);
    assert.equal(seen[1]?.['x-token'], sentFirst, 'the same value the second time');
    assert.deepEqual(await store.secretOf(ref, GEN), { ok: true, value: sentFirst }, 'and the one the hook reads');
    assert.equal(JSON.stringify(events).includes(sentFirst ?? 'x'), false, 'never in the record');
    assert.equal(JSON.stringify([first, second]).includes(sentFirst ?? 'x'), false, 'never in the answer');
  });

  it('a secret that is not generated and has no value is still `disabled` with missing', async () => {
    const { store } = storeOf();
    const plain: ExternalSystemDeclaration = { ...declaration, settings: [{ id: 'account', secret: false }, { id: 'signingKey', secret: true }] };
    const result = await senderOf(store, [], [], plain).sendExternal(ref, 'notify', notify, { organizationId: 'org' });
    assert.equal(result.ok === false && result.code, 'disabled');
    assert.deepEqual(result.ok === false && result.missing, ['signingKey']);
  });
});

describe('rt331 s2: clear (delete a setting)', () => {
  it('a generated secret is swapped: after clear the next outbound call makes ANOTHER value; the hook reads the new one', async () => {
    const { store } = storeOf();
    const first = await store.ensureGeneratedSecret(ref, GEN);
    assert.deepEqual(await store.clear(ref, GEN, 'admin'), { ok: true });
    assert.deepEqual(await store.secretOf(ref, GEN), { ok: true, value: undefined }, 'nothing to read until the next activation');
    const second = await store.ensureGeneratedSecret(ref, GEN);
    assert.equal(first.ok && second.ok && first.value !== second.value, true);
  });

  it('a secret that is not generated, once cleared, leaves the outbound call `disabled` with missing', async () => {
    const { store } = storeOf();
    assert.deepEqual(await store.set(ref, 'manualKey', 'typed-by-hand', 'admin'), { ok: true });
    assert.deepEqual(await store.clear(ref, 'manualKey', 'admin'), { ok: true });
    assert.deepEqual(await store.secretOf(ref, 'manualKey'), { ok: true, value: undefined });
  });

  it('a setting that is not in the declaration is refused', async () => {
    const { store } = storeOf();
    assert.deepEqual(await store.clear(ref, 'nothing', 'admin'), { ok: false, code: 'refused' });
  });
});
